  "simple.c2pa_bandcamp": "رابط Bandcamp",
  "page.about": "<h2>عن RedoSan Authenticity</h2><p><strong>RedoSan Authenticity</strong> هي أداة أصالة رقمية مفتوحة المصدر تعمل بالكامل في متصفحك. لا يتم رفع أي ملفات إلى أي خادم — جميع المعالجة تحدث على جهازك.</p><p>نوفر مجموعة شاملة من الأدوات للطب الشرعي الرقمي والتحقق من الوسائط:</p><ul><li><strong>العلامة المائية</strong> — 9 خوارزميات تشمل LSB و DCT و DWT والعلامة المائية العصبية والطب الشرعي</li><li><strong>البصمة</strong> — التجزئة التشفيرية (SHA-1/2/3 و BLAKE2/3 و MD5 و RIPEMD-160 و Whirlpool) وبصمات الصور الإدراكية</li><li><strong>البيانات الوصفية</strong> — قراءة EXIF والأبعاد والتنسيق ووضع الألوان من الصور</li><li><strong>الطابع الزمني</strong> — تجزئة SHA-256 مع دعم التحقق من OpenTimestamps</li></ul><p>بُنيت مع الخصوصية كمبدأ أساسي. ملفاتك لا تغادر جهازك أبدًا.</p>",
  "page.privacy": "<h2>سياسة الخصوصية</h2><p><strong>بياناتك تبقى على جهازك.</strong> RedoSan Authenticity هو تطبيق يعمل بالكامل على جهاز العميل. جميع المعالجة تتم في متصفحك باستخدام JavaScript. لا يتم إرسال أي ملفات أو بيانات وصفية أو أي بيانات أخرى إلى أي خادم.</p><h3>ما نجمعه</h3><p>لا شيء. لا نقوم بجمع أو تخزين أو إرسال أي بيانات شخصية أو ملفات أو تحليلات. يعمل التطبيق بالكامل على GitHub Pages ولا يوجد خادم خلفي.</p><h3>مكتبات الطرف الثالث</h3><p>نقوم بتحميل مكتبات JavaScript من شبكات توصيل المحتوى (<a href=\"https://cdnjs.cloudflare.com\" target=\"_blank\" rel=\"noopener\">cdnjs</a> و <a href=\"https://www.jsdelivr.com\" target=\"_blank\" rel=\"noopener\">jsdelivr</a>) لوظائف تصدير PDF و DOCX. قد يكون لشبكات CDN هذه سجلاتها وتحليلاتها الخاصة. لا تتم مشاركة أي بيانات من ملفاتك مع هذه الخدمات.</p><h3>التغييرات</h3><p>قد يتم تحديث هذه السياسة من وقت لآخر. الاستمرار في استخدام الأداة يشكل قبولاً للسياسة الحالية.</p>",
  "page.contact": "<h2>اتصل بنا</h2><p>هل لديك أسئلة أو اقتراحات أو وجدت خطأ؟ يسعدنا سماع رأيك.</p>",
  "page.social": "<h2>تابعنا</h2><p>ابق على اتصال وتابع RedoSan على وسائل التواصل الاجتماعي.</p>",
