  "page.about": "<h2>Über RedoSan Authenticity</h2><p><strong>RedoSan Authenticity</strong> ist ein Open-Source-Digital-Authentizitätstool, das vollständig in Ihrem Browser läuft. Es werden niemals Dateien auf einen Server hochgeladen — alle Verarbeitungen finden clientseitig statt.</p><p>Wir bieten eine umfassende Suite von Tools für digitale Forensik und Medienverifizierung:</p><ul><li><strong>Wasserzeichen</strong> — 9 Algorithmen einschließlich LSB, DCT, DWT, Neural-Style und forensische Wasserzeichen</li><li><strong>Fingerabdruck</strong> — Kryptografisches Hashing (SHA-1/2/3, BLAKE2/3, MD5, RIPEMD-160, Whirlpool) und Wahrnehmungsbild-Hashing</li><li><strong>Metadaten</strong> — EXIF, Abmessungen, Format und Farbmodus aus Bildern lesen</li><li><strong>Zeitstempel</strong> — SHA-256 Hashing mit OpenTimestamps-Verifizierungsunterstützung</li></ul><p>Gebaut mit Datenschutz als Kernprinzip. Ihre Dateien verlassen niemals Ihr Gerät.</p>",
  "page.privacy": "<h2>Datenschutzerklärung</h2><p><strong>Ihre Daten bleiben auf Ihrem Gerät.</strong> RedoSan Authenticity ist eine 100% Client-seitige Anwendung. Alle Verarbeitungen erfolgen in Ihrem Browser mit JavaScript. Es werden keine Dateien, Metadaten oder anderen Daten an einen Server übertragen.</p><h3>Was wir sammeln</h3><p>Nichts. Wir sammeln, speichern oder übertragen keine persönlichen Daten, Dateien oder Analysen. Die Anwendung läuft vollständig auf GitHub Pages und es ist kein Backend-Server involviert.</p><h3>Drittanbieter-Bibliotheken</h3><p>Wir laden JavaScript-Bibliotheken von CDNs (<a href=\"https://cdnjs.cloudflare.com\" target=\"_blank\" rel=\"noopener\">cdnjs</a> und <a href=\"https://www.jsdelivr.com\" target=\"_blank\" rel=\"noopener\">jsdelivr</a>) für PDF- und DOCX-Export-Funktionalität. Diese CDNs können eigene Logging- und Analysedienste haben. Es werden keine Daten aus Ihren Dateien mit diesen Diensten geteilt.</p><h3>Änderungen</h3><p>Diese Richtlinie kann gelegentlich aktualisiert werden. Die fortgesetzte Nutzung des Tools stellt die Akzeptanz der aktuellen Richtlinie dar.</p>",
  "page.contact": "<h2>Kontaktieren Sie uns</h2><p>Haben Sie Fragen, Vorschläge oder einen Fehler gefunden? Wir würden gerne von Ihnen hören.</p>",
  "page.social": "<h2>Folgen Sie uns</h2><p>Bleiben Sie verbunden und folgen Sie RedoSan in sozialen Medien.</p>",
