  "page.about": "<h2>Acerca de RedoSan Authenticity</h2><p><strong>RedoSan Authenticity</strong> es una herramienta de autenticidad digital de código abierto que se ejecuta completamente en su navegador. Nunca se suben archivos a ningún servidor — todo procesamiento ocurre del lado del cliente.</p><p>Proporcionamos una suite completa de herramientas para forense digital y verificación de medios:</p><ul><li><strong>Marcado de Agua</strong> — 9 algoritmos incluyendo LSB, DCT, DWT, estilo neuronal y marcado de agua forense</li><li><strong>Huella Digital</strong> — Hash criptográfico (SHA-1/2/3, BLAKE2/3, MD5, RIPEMD-160, Whirlpool) y hash de imagen perceptual</li><li><strong>Metadatos</strong> — Leer EXIF, dimensiones, formato y modo de color de imágenes</li><li><strong>Marcado de Tiempo</strong> — Hash SHA-256 con soporte de verificación OpenTimestamps</li></ul><p>Construido con la privacidad como principio fundamental. Sus archivos nunca dejan su dispositivo.</p>",
  "page.privacy": "<h2>Política de Privacidad</h2><p><strong>Sus datos permanecen en su dispositivo.</strong> RedoSan Authenticity es una aplicación 100% del lado del cliente. Todo procesamiento se realiza en su navegador usando JavaScript. No se transmiten archivos, metadatos o cualquier otro dato a ningún servidor.</p><h3>Qué recopilamos</h3><p>Nada. No recopilamos, almacenamos o transmitimos datos personales, archivos o análisis. La aplicación se ejecuta completamente en GitHub Pages y no hay servidor backend involucrado.</p><h3>Bibliotecas de terceros</h3><p>Cargamos bibliotecas JavaScript desde CDNs (<a href=\"https://cdnjs.cloudflare.com\" target=\"_blank\" rel=\"noopener\">cdnjs</a> y <a href=\"https://www.jsdelivr.com\" target=\"_blank\" rel=\"noopener\">jsdelivr</a>) para funcionalidad de exportación PDF y DOCX. Estos CDNs pueden tener su propio registro y análisis. No se comparten datos de sus archivos con estos servicios.</p><h3>Cambios</h3><p>Esta política puede actualizarse ocasionalmente. El uso continuado de la herramienta constituye la aceptación de la política actual.</p>",
  "page.contact": "<h2>Contáctenos</h2><p>¿Tiene preguntas, sugerencias o encontró un error? Nos encantaría saber de usted.</p>",
  "page.social": "<h2>Síganos</h2><p>Manténgase conectado y siga a RedoSan en redes sociales.</p>",
