  "simple.pi_done": "Message secret injecté avec succès. Téléchargement disponible sur la page finale.",
  "page.about": "<h2>À propos de RedoSan Authenticity</h2><p><strong>RedoSan Authenticity</strong> est un outil d'authenticité numérique open-source qui fonctionne entièrement dans votre navigateur. Aucun fichier n'est jamais téléchargé sur aucun serveur — tout traitement se produit côté client.</p><p>Nous fournissons une suite complète d'outils pour la forensique numérique et la vérification des médias :</p><ul><li><strong>Filigranage</strong> — 9 algorithmes incluant LSB, DCT, DWT, style neuronal et filigrane forensique</li><li><strong>Empreinte</strong> — Hachage cryptographique (SHA-1/2/3, BLAKE2/3, MD5, RIPEMD-160, Whirlpool) et hachage d'image perceptuel</li><li><strong>Métadonnées</strong> — Lire EXIF, dimensions, format et mode couleur des images</li><li><strong>Horodatage</strong> — Hachage SHA-256 avec support de vérification OpenTimestamps</li></ul><p>Construit avec la confidentialité comme principe fondamental. Vos fichiers ne quittent jamais votre appareil.</p>",
  "page.privacy": "<h2>Politique de Confidentialité</h2><p><strong>Vos données restent sur votre appareil.</strong> RedoSan Authenticity est une application 100% côté client. Tout traitement est effectué dans votre navigateur en utilisant JavaScript. Aucun fichier, métadonnée ou autre donnée n'est transmis à aucun serveur.</p><h3>Ce que nous collectons</h3><p>Rien. Nous ne collectons, stockons ou transmettons aucune donnée personnelle, fichier ou analytique. L'application fonctionne entièrement sur GitHub Pages et aucun serveur backend n'est impliqué.</p><h3>Bibliothèques tierces</h3><p>Nous chargeons des bibliothèques JavaScript depuis des CDN (<a href=\"https://cdnjs.cloudflare.com\" target=\"_blank\" rel=\"noopener\">cdnjs</a> et <a href=\"https://www.jsdelivr.com\" target=\"_blank\" rel=\"noopener\">jsdelivr</a>) pour les fonctionnalités d'exportation PDF et DOCX. Ces CDN peuvent avoir leurs propres logs et analytiques. Aucune donnée de vos fichiers n'est partagée avec ces services.</p><h3>Changements</h3><p>Cette politique peut être mise à jour occasionnellement. L'utilisation continue de l'outil constitue l'acceptation de la politique actuelle.</p>",
  "page.contact": "<h2>Nous Contacter</h2><p>Des questions, suggestions ou trouvé un bug ? Nous aimerions avoir de vos nouvelles.</p>",
  "page.social": "<h2>Suivez-nous</h2><p>Restez connecté et suivez RedoSan sur les réseaux sociaux.</p>",
