  "page.about": "<h2>关于RedoSan Authenticity</h2><p><strong>RedoSan Authenticity</strong>是一个完全在浏览器中运行的开源数字真实性工具。没有任何文件上传到任何服务器 — 所有处理都在客户端进行。</p><p>我们为数字取证和媒体验证提供全面的工具套件：</p><ul><li><strong>水印</strong> — 9种算法，包括LSB、DCT、DWT、神经风格和取证水印</li><li><strong>指纹</strong> — 加密哈希（SHA-1/2/3、BLAKE2/3、MD5、RIPEMD-160、Whirlpool）和感知图像哈希</li><li><strong>元数据</strong> — 从图像读取EXIF、尺寸、格式和颜色模式</li><li><strong>时间戳</strong> — SHA-256哈希，支持OpenTimestamps验证</li></ul><p>以隐私为核心原则构建。您的文件永远不会离开您的设备。</p>",
  "page.privacy": "<h2>隐私政策</h2><p><strong>您的数据保留在您的设备上。</strong> RedoSan Authenticity是100%客户端应用程序。所有处理都在您的浏览器中使用JavaScript进行。没有任何文件、元数据或任何其他数据传输到任何服务器。</p><h3>我们收集什么</h3><p>什么都没有。我们不收集、存储或传输任何个人数据、文件或分析。应用程序完全在GitHub Pages上运行，不涉及后端服务器。</p><h3>第三方库</h3><p>我们从CDN（<a href=\"https://cdnjs.cloudflare.com\" target=\"_blank\" rel=\"noopener\">cdnjs</a>和<a href=\"https://www.jsdelivr.com\" target=\"_blank\" rel=\"noopener\">jsdelivr</a>）加载JavaScript库用于PDF和DOCX导出功能。这些CDN可能有自己的日志和分析。您文件的任何数据都不会与这些服务共享。</p><h3>变更</h3><p>本政策可能会偶尔更新。继续使用该工具即表示接受当前政策。</p>",
  "page.contact": "<h2>联系我们</h2><p>有问题、建议或发现错误？我们很乐意听取您的意见。</p>",
  "page.social": "<h2>关注我们</h2><p>保持联系并在社交媒体上关注RedoSan。</p>",
